C={}
def put(v,spec):
    for tok in spec.split():
        rng,cat=tok.split('=')
        if '-' in rng: a,b=map(int,rng.split('-'))
        else: a=b=int(rng)
        for i in range(a,b+1): C[(v,i)]=cat
